-- Replace the refunded demo case and expand the store account to a realistic demo portfolio.
DELETE FROM orders WHERE owner_id=2 AND order_no='DEMO-VERO-1008';
DELETE FROM customers WHERE owner_id=2 AND channel_code='DEMO-VERO-08';


SELECT 2,printf('DEMO-VERO-%04d',2000 + c.id * 10 + n.n),c.id,'{}',CASE n.n WHEN 1 THEN 'completed' WHEN 2 THEN 'shipped' ELSE 'production' END,'paid',CASE n.n WHEN 1 THEN 'jacket' WHEN 2 THEN 'trousers' ELSE 'shirt' END,CASE n.n WHEN 1 THEN 'Business Suit Reorder' WHEN 2 THEN 'Pleated Trousers Reorder' ELSE 'Custom Stripe Shirt' END,CASE n.n WHEN 1 THEN 'VBC-110-NV' WHEN 2 THEN 'TR-121-NV' ELSE 'SH-102-ST' END,CASE n.n WHEN 1 THEN 'Navy Wool' WHEN 2 THEN 'Classic Navy' ELSE 'Blue Stripe' END,CASE n.n WHEN 1 THEN 'Vitale Barberis Canonico' WHEN 2 THEN 'House Collection' ELSE 'Albini' END,CASE n.n WHEN 1 THEN 1300 WHEN 2 THEN 1080 ELSE 1550 END,0,CASE n.n WHEN 1 THEN 180 WHEN 2 THEN 120 ELSE 230 END,200,CASE n.n WHEN 1 THEN 1680 WHEN 2 THEN 1400 ELSE 2000 END,'USD',CASE n.n WHEN 1 THEN 1.3 WHEN 2 THEN 0.7 ELSE 0.4 END,'[]','[]','{}',c.channel_code,'2026-09-04 18:00:00','2026-09-04 18:00:00'
FROM customers c CROSS JOIN (SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3) n
WHERE c.owner_id=2 AND c.channel_code LIKE 'DEMO-VERO-2%' AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.order_no=printf('DEMO-VERO-%04d',2000 + c.id * 10 + n.n));
